import{_ as s,c as a,o as n,a6 as p}from"./chunks/framework.C2DR_BI-.js";const _=JSON.parse('{"title":"FFmpeg使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"modules/more/ffmpeg/learn-ffmpeg/src/B_FFmpeg使用指南.md","filePath":"modules/more/ffmpeg/learn-ffmpeg/src/B_FFmpeg使用指南.md","lastUpdated":1774171177000}'),e={name:"modules/more/ffmpeg/learn-ffmpeg/src/B_FFmpeg使用指南.md"},l=p(`<h1 id="ffmpeg使用指南" tabindex="-1">FFmpeg使用指南 <a class="header-anchor" href="#ffmpeg使用指南" aria-label="Permalink to &quot;FFmpeg使用指南&quot;">​</a></h1><h4 id="ffmpeg是什么" tabindex="-1">FFmpeg是什么 <a class="header-anchor" href="#ffmpeg是什么" aria-label="Permalink to &quot;FFmpeg是什么&quot;">​</a></h4><p>​ ffmpeg(命令行工具) 是一个快速的音视频转换工具。</p><h4 id="ffmpeg使用方法" tabindex="-1">FFmpeg使用方法 <a class="header-anchor" href="#ffmpeg使用方法" aria-label="Permalink to &quot;FFmpeg使用方法&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ffmpeg [全局选项] {[输入文件选项] -i &#39;输入文件&#39;} ... {[输出文件选项] &#39;输出文件&#39;}</span></span></code></pre></div><h4 id="主要选项" tabindex="-1">主要选项 <a class="header-anchor" href="#主要选项" aria-label="Permalink to &quot;主要选项&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>‘-f fmt (input/output)’ </span></span>
<span class="line"><span>	强制输入或输出文件格式。通常，输入文件的格式是自动检测的，</span></span>
<span class="line"><span>	输出文件的格式是通过文件扩展名来进行猜测的，所有该选项大</span></span>
<span class="line"><span>	多数时候不需要。</span></span>
<span class="line"><span>‘-i filename (input)’ </span></span>
<span class="line"><span>	输入文件名</span></span>
<span class="line"><span>‘-y (global)’ </span></span>
<span class="line"><span>	覆盖输出文件而不询问</span></span>
<span class="line"><span>‘-n (global)’ </span></span>
<span class="line"><span>	不覆盖输出文件，如果一个给定的输出文件已经存在，则立即</span></span>
<span class="line"><span>	退出</span></span>
<span class="line"><span>‘-c[:stream_specifier] codec (input/output,per-stream)’</span></span>
<span class="line"><span>‘-codec[:stream_specifier] codec (input/output,per-stream)’</span></span>
<span class="line"><span>	为一个或多个流选择一个编码器(当使用在一个输出文件之前时)</span></span>
<span class="line"><span>	或者一个解码器(当使用在一个输入文件之前时)。codec 是一个</span></span>
<span class="line"><span>	编码器/解码器名称或者一个特定值“copy”(只适用输出)。</span></span>
<span class="line"><span>‘-t duration (output)’ </span></span>
<span class="line"><span>	当到达 duration 时，停止写输出。</span></span>
<span class="line"><span>	duration 可以是一个数字(秒)，或者使用hh:mm:ss[.xxx]形式。</span></span>
<span class="line"><span>	-to 和 -t 是互斥的，-t 优先级更高。</span></span>
<span class="line"><span>‘-to position (output)’ </span></span>
<span class="line"><span>	在 position 处停止写输出。</span></span>
<span class="line"><span>	duration 可以是一个数字(秒)，或者使用hh:mm:ss[.xxx]形式。</span></span>
<span class="line"><span>	-to 和 -t 是互斥的，-t 优先级更高。</span></span>
<span class="line"><span>‘-fs limit_size (output)’</span></span>
<span class="line"><span>	设置文件大小限制，以字节表示</span></span>
<span class="line"><span>‘-ss position (input/output)’</span></span>
<span class="line"><span>	当作为输入选项时(在 -i 之前)，在输入文件中跳转到 position。</span></span>
<span class="line"><span>	需要注意的是，在大多数格式中，不太可能精确的跳转，因此，</span></span>
<span class="line"><span>	ffmpeg 将跳转到 position 之前最接近的位置。当进行转码</span></span>
<span class="line"><span>	并且 ‘-accurate_seek’ 打开时(默认)，位于跳转点和 position </span></span>
<span class="line"><span>	之间的额外部分将被解码并且丢弃。当做流拷贝或者当使用</span></span>
<span class="line"><span>	‘-noaccurate_seek’时，它将被保留下来。</span></span>
<span class="line"><span>	当作为输出选项时(在输出文件名前)，解码但是丢弃输入，直到</span></span>
<span class="line"><span>	时间戳到达 position。</span></span>
<span class="line"><span>	position 可以是秒或者 hh:mm:ss[.xxx] 形式</span></span>
<span class="line"><span>‘-itsoffset offset (input)’</span></span>
<span class="line"><span>	设置输入时间偏移。 offset 将被添加到输入文件的时间戳。指定</span></span>
<span class="line"><span>	一个正偏移，意味着相应的流将被延时指定时间。</span></span>
<span class="line"><span>‘-timestamp date (output)’</span></span>
<span class="line"><span>	在容器中设置录音时间戳</span></span>
<span class="line"><span>‘-metadata[:metadata_specifier] key=value (output,per-metadata)’</span></span>
<span class="line"><span>	设置metadata key/value对</span></span>
<span class="line"><span>‘-target type (output)’</span></span>
<span class="line"><span>	指定目标文件类型(vcd, svcd, dvd, dv, dv50)。</span></span>
<span class="line"><span>	type 可以带有 pal-, ntsc- 或 film- 前缀，以使用相应的标准。</span></span>
<span class="line"><span>	所有的格式选项(bitrate, codecs, buffer sizes)将自动设定。</span></span>
<span class="line"><span>‘-dframes number (output)’</span></span>
<span class="line"><span>	设置要录制数据帧的个数。这是 -frames:d 的别名</span></span>
<span class="line"><span>‘-frames[:stream_specifier] framecount (output,per-stream)’  </span></span>
<span class="line"><span>	framecount 帧以后，停止写流。</span></span>
<span class="line"><span>‘-q[:stream_specifier] q (output,per-stream)’</span></span>
<span class="line"><span>‘-qscale[:stream_specifier] q (output,per-stream)’ </span></span>
<span class="line"><span>	使用固定质量范围(VBR)。</span></span>
<span class="line"><span>‘-filter[:stream_specifier] filtergraph (output,per-stream)’</span></span>
<span class="line"><span>	创建filtergraph 指定的过滤图，并使用它来过滤流。</span></span>
<span class="line"><span>‘-filter_script[:stream_specifier] filename (output,per-stream)’</span></span>
<span class="line"><span>	该选项与‘-filter’相似，唯一的不同是，它的参数是一个存放</span></span>
<span class="line"><span>	过滤图的文件的名称。</span></span>
<span class="line"><span>‘-pre[:stream_specifier] preset_name (output,per-stream)’ </span></span>
<span class="line"><span>	指定匹配流的预设</span></span>
<span class="line"><span>‘-stats (global)’</span></span>
<span class="line"><span>	打印编码进程/统计信息。默认打开，可以使用 -nostats 禁用。</span></span>
<span class="line"><span>‘-stdin’ </span></span>
<span class="line"><span>	开启标准输入交互。默认打开，除非标准输入作为一个输入。</span></span>
<span class="line"><span>	可以使用 -nostdin 禁止。</span></span>
<span class="line"><span>‘-debug_ts (global)’</span></span>
<span class="line"><span>	打印时间戳信息。默认关闭。</span></span>
<span class="line"><span>‘-attach filename (output)’</span></span>
<span class="line"><span>	添加一个附件到输出文件中</span></span>
<span class="line"><span>‘-dump_attachment[:stream_specifier] filename (input,per-stream)’ </span></span>
<span class="line"><span>	提取匹配的附件流到filename指定的文件中。</span></span></code></pre></div><h4 id="视频选项" tabindex="-1">视频选项 <a class="header-anchor" href="#视频选项" aria-label="Permalink to &quot;视频选项&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>‘-vframes number (output)’</span></span>
<span class="line"><span>	设置录制视频帧的个数。这是 -frames:v 的别名</span></span>
<span class="line"><span>‘-r[:stream_specifier] fps (input/output,per-stream)’</span></span>
<span class="line"><span>	设置帧率(Hz 值， 分数或缩写)</span></span>
<span class="line"><span>‘-s[:stream_specifier] size (input/output,per-stream)’</span></span>
<span class="line"><span>	设置帧大小。格式为 ‘wxh’ (默认与源相同)</span></span>
<span class="line"><span>‘-aspect[:stream_specifier] aspect (output,per-stream)’</span></span>
<span class="line"><span>	设置视频显示长宽比</span></span>
<span class="line"><span>‘-vn (output)’</span></span>
<span class="line"><span>	禁止视频录制</span></span>
<span class="line"><span>‘-vcodec codec (output)’</span></span>
<span class="line"><span>	设置视频 codec。这是 -codec:v 的别名</span></span>
<span class="line"><span>‘-pass[:stream_specifier] n (output,per-stream)’</span></span>
<span class="line"><span>	选择pass number (1 or 2)。用来进行双行程视频编码。</span></span>
<span class="line"><span>‘-passlogfile[:stream_specifier] prefix (output,per-stream)’</span></span>
<span class="line"><span>	设置 two-pass 日志文件名前缀，默认为“ffmpeg2pass”。</span></span>
<span class="line"><span>‘-vf filtergraph (output)’</span></span>
<span class="line"><span>	创建 filtergraph 指定的过滤图，并使用它来过滤流。</span></span>
<span class="line"><span>‘-pix_fmt[:stream_specifier] format (input/output,per-stream)’</span></span>
<span class="line"><span>	设置像素格式。</span></span>
<span class="line"><span>‘-sws_flags flags (input/output)’</span></span>
<span class="line"><span>	设置软缩放标志</span></span>
<span class="line"><span>‘-vdt n’</span></span>
<span class="line"><span>	丢弃阈值</span></span>
<span class="line"><span>‘-psnr’</span></span>
<span class="line"><span>	计算压缩帧的 PSNR </span></span>
<span class="line"><span>‘-vstats’</span></span>
<span class="line"><span>	复制视频编码统计信息到‘vstats_HHMMSS.log’</span></span>
<span class="line"><span>‘-vstats_file file’</span></span>
<span class="line"><span>	复制视频编码统计信息到 file</span></span>
<span class="line"><span>‘-force_key_frames[:stream_specifier] time[,time...] (output,per-stream)’</span></span>
<span class="line"><span>‘-force_key_frames[:stream_specifier] expr:expr (output,per-stream)’</span></span>
<span class="line"><span>	在指定的时间戳强制关键帧</span></span>
<span class="line"><span>‘-copyinkf[:stream_specifier] (output,per-stream)’</span></span>
<span class="line"><span>	当进行流拷贝时，同时拷贝开头的非关键帧</span></span>
<span class="line"><span>‘-hwaccel[:stream_specifier] hwaccel (input,per-stream)’</span></span>
<span class="line"><span>	使用硬件加速来解码匹配的流</span></span>
<span class="line"><span>‘-hwaccel_device[:stream_specifier] hwaccel_device (input,per-stream)’</span></span>
<span class="line"><span>	选择硬件加速所使用的设备。该选项只有‘-hwaccel’同时指定时才有意义。</span></span></code></pre></div><h4 id="音频选项" tabindex="-1">音频选项 <a class="header-anchor" href="#音频选项" aria-label="Permalink to &quot;音频选项&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>‘-aframes number (output)’</span></span>
<span class="line"><span>	设置录制音频帧的个数。这是 -frames:a 的别名</span></span>
<span class="line"><span>‘-ar[:stream_specifier] freq (input/output,per-stream)’</span></span>
<span class="line"><span>	设置音频采样率。</span></span>
<span class="line"><span>‘-aq q (output)’</span></span>
<span class="line"><span>	设置音频质量。这是 -q:a 的别名</span></span>
<span class="line"><span>‘-ac[:stream_specifier] channels (input/output,per-stream)’</span></span>
<span class="line"><span>	设置音频通道数。</span></span>
<span class="line"><span>‘-an (output)’</span></span>
<span class="line"><span>	禁止音频录制</span></span>
<span class="line"><span>‘-acodec codec (input/output)’</span></span>
<span class="line"><span>	设置音频codec。这是-codec:a的别名</span></span>
<span class="line"><span>‘-sample_fmt[:stream_specifier] sample_fmt (output,per-stream)’</span></span>
<span class="line"><span>	设置音频采样格式</span></span>
<span class="line"><span>‘-af filtergraph (output)’</span></span>
<span class="line"><span>	创建filtergraph 所指定的过滤图，并使用它来过滤流</span></span></code></pre></div><h4 id="高级选项" tabindex="-1">高级选项 <a class="header-anchor" href="#高级选项" aria-label="Permalink to &quot;高级选项&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>‘-map [-]input_file_id[:stream_specifier][,sync_file_id[:stream_specifier]] | [linklabel] (output)’</span></span>
<span class="line"><span>	指定一个或多个流作为输出文件的源。</span></span>
<span class="line"><span>	命令行中的第一个 -map 选项，指定输出流0的源，</span></span>
<span class="line"><span>	第二个 -map 选项，指定输出流1的源，等等。</span></span>
<span class="line"><span>‘-map_channel [input_file_id.stream_specifier.channel_id|-1][:output_file_id.stream_specifier]’</span></span>
<span class="line"><span>	将一个给定输入的音频通道映射到一个输出。</span></span>
<span class="line"><span>‘-map_metadata[:metadata_spec_out] infile[:metadata_spec_in] (output,per-metadata)’</span></span>
<span class="line"><span>	设置下一个输出文件的 metadata 信息。</span></span>
<span class="line"><span>‘-map_chapters input_file_index (output)’</span></span>
<span class="line"><span>	从索引号为 input_file_index 的输入文件中拷贝章节到下一个输出文件中。</span></span>
<span class="line"><span>‘-timelimit duration (global)’</span></span>
<span class="line"><span>	ffmpeg 运行 duration 秒后推出</span></span>
<span class="line"><span>‘-dump (global)’</span></span>
<span class="line"><span>	将每一个输入包复制到标准输出</span></span>
<span class="line"><span>‘-hex (global)’</span></span>
<span class="line"><span>	复制包时，同时复制负载</span></span>
<span class="line"><span>‘-re (input)’</span></span>
<span class="line"><span>	以本地帧率读取数据。主要用来模拟一个采集设备，</span></span>
<span class="line"><span>	或者实时输入流(例如：当从一个文件读取时).</span></span>
<span class="line"><span>‘-vsync parameter’</span></span>
<span class="line"><span>	视频同步方法</span></span>
<span class="line"><span>‘-async samples_per_second’</span></span>
<span class="line"><span>	音频同步方法</span></span>
<span class="line"><span>‘-shortest (output)’</span></span>
<span class="line"><span>	当最短的输入流结束时，终止编码</span></span>
<span class="line"><span>‘-muxdelay seconds (input)’</span></span>
<span class="line"><span>	设置最大解封装-解码延时</span></span>
<span class="line"><span>‘-muxpreload seconds (input)’</span></span>
<span class="line"><span>	设置初始解封装-解码延时</span></span>
<span class="line"><span>‘-streamid output-stream-index:new-value (output)’</span></span>
<span class="line"><span>	为一个输出流分配一个新的stream-id。</span></span>
<span class="line"><span>‘-bsf[:stream_specifier] bitstream_filters (output,per-stream)’</span></span>
<span class="line"><span>	为匹配的流设置比特流过滤器</span></span>
<span class="line"><span>‘-filter_complex filtergraph (global)’</span></span>
<span class="line"><span>	定义一个复杂的过滤图</span></span>
<span class="line"><span>‘-lavfi filtergraph (global)’</span></span>
<span class="line"><span>	定义一个复杂的过滤图。相当于‘-filter_complex’</span></span>
<span class="line"><span>‘-filter_complex_script filename (global)’</span></span>
<span class="line"><span>   该选项类似于‘-filter_complex’，唯一的不同是</span></span>
<span class="line"><span>   它的参数是一个定义过滤图的文件的文件名</span></span>
<span class="line"><span>‘-accurate_seek (input)’</span></span>
<span class="line"><span>   打开或禁止在输入文件中的精确跳转。默认打开。</span></span></code></pre></div><h4 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h4><ul><li><a href="http://www.tuicool.com/articles/nquMZv" target="_blank" rel="noreferrer">FFmpeg 使用指南</a></li></ul>`,15),t=[l];function i(c,r,o,u,m,f){return n(),a("div",null,t)}const h=s(e,[["render",i]]);export{_ as __pageData,h as default};
